        CODEX_ACP_DESCRIPTOR_ID => {
            let runtime = CodexAcpRuntime::discover(
                placement,
                CodexAcpSessionPreferences::default(),
            )
            .map_err(|error| error.to_string())?;
            self.acp
                .register(Box::new(runtime))
                .map_err(|error| error.to_string())
        }
        CLAUDE_ACP_AGENT_ID => {
