                .map_err(|error| error.to_string())?;
            let runtime = AcpProcessRuntime::new(registration.descriptor)
                .map_err(|error| error.to_string())?;
            self.acp
                .register(Box::new(runtime))
                .map_err(|error| error.to_string())
        }
        _ => Err(format!("ACP agent `{agent_id}` is not configured by AI Studio")),
    }
